import { Context } from "effect";
import { MediaClient } from "./media-client.js";
import { TranscriptionFinishEvent, } from "./transcription.js";
export class TranscriptionClientService extends Context.Service()("@opencode/TranscriptionClient") {
}
export const Service = TranscriptionClientService;
export const TranscriptionClient = {
    Service,
    ...MediaClient.make(Service, {
        modality: "transcription",
        responseEvents: (response) => [TranscriptionFinishEvent.make({ ...response })],
    }),
};
